`timescale 1ns/1ps
// Golden ROM is generated by independent Python/C++ integer models. Unity
// calibration and a startup count divisible by 1024 PDM periods are required.
module pcm_selftest_checker #(
    parameter integer FIRST_FRAME=96,
    parameter integer PASS_FRAMES=48000,
    parameter integer TIMEOUT_CYCLES=12288000
) (
    input wire clk,rst_n,enable,
    input wire [23:0] pcm_data,
    input wire [6:0] pcm_channel,
    input wire [63:0] pcm_frame_id,
    input wire pcm_valid,pcm_ready,pcm_first,pcm_last,
    input wire pipeline_error,
    output wire passed,
    output reg failed,
    output reg [31:0] checked_frames,
    output reg [63:0] first_bad_frame,
    output reg [6:0] first_bad_channel
);
    reg [23:0] expected_rom[0:2047];
    initial begin
        `include "selftest_expected.svh"
    end
    reg [23:0] expected_q,actual_q;
    reg compare_valid;
    reg [63:0] frame_q,expected_frame;
    reg [6:0] channel_q,expected_channel;
    reg last_q,position_bad_q;
    reg [31:0] idle_cycles;
    wire accept=pcm_valid && pcm_ready;
    wire mismatch=compare_valid && (actual_q!=expected_q || position_bad_q);
    assign passed=enable && !failed && checked_frames>=PASS_FRAMES;
    // Keep the ROM read synchronous, separate from the state/control reset.
    always @(posedge clk)
        if(enable && accept) expected_q<=expected_rom[{pcm_frame_id[3:0],pcm_channel}];
    always @(posedge clk) begin
        if(!rst_n || !enable) begin
            failed<=0;checked_frames<=0;first_bad_frame<=0;first_bad_channel<=0;
            expected_channel<=0;expected_frame<=FIRST_FRAME;compare_valid<=0;
            actual_q<=0;frame_q<=0;channel_q<=0;last_q<=0;position_bad_q<=0;idle_cycles<=0;
        end else begin
            compare_valid<=accept;
            if(accept) begin
                idle_cycles<=0;actual_q<=pcm_data;frame_q<=pcm_frame_id;
                channel_q<=pcm_channel;last_q<=pcm_last;
                position_bad_q<=pcm_channel!=expected_channel || pcm_frame_id!=expected_frame ||
                    pcm_first!=(expected_channel==0) || pcm_last!=(expected_channel==127);
                if(expected_channel==127) begin expected_channel<=0;expected_frame<=expected_frame+1'b1;end
                else expected_channel<=expected_channel+1'b1;
            end else if(idle_cycles<TIMEOUT_CYCLES) idle_cycles<=idle_cycles+1'b1;
            if(compare_valid && last_q && !failed && !mismatch && checked_frames!=32'hffffffff)
                checked_frames<=checked_frames+1'b1;
            if(!failed && (mismatch || pipeline_error || idle_cycles==TIMEOUT_CYCLES)) begin
                failed<=1;first_bad_frame<=mismatch ? frame_q : expected_frame;
                first_bad_channel<=mismatch ? channel_q : expected_channel;
            end
        end
    end
    // synthesis translate_off
    initial if(FIRST_FRAME<96 || PASS_FRAMES<16 || TIMEOUT_CYCLES<1)
        $fatal(1,"Invalid self-test checker parameters");
    // synthesis translate_on
endmodule
